"""Private object storage interface."""

from __future__ import annotations

import re
from collections.abc import AsyncIterator
from dataclasses import dataclass
from typing import IO, Protocol

# Keys are generated by the backend from UUIDs; anything else is rejected, so a
# key can never contain "..", a leading slash or a client-supplied filename.
_KEY_RE = re.compile(r"^owners/[0-9a-f\-]{36}/[a-z]+/[0-9a-f\-]{36}/[a-z0-9_.\-]{1,64}$")


class InvalidStorageKey(ValueError):
    pass


def validate_key(key: str) -> str:
    if not _KEY_RE.match(key) or ".." in key:
        raise InvalidStorageKey("invalid storage key")
    return key


@dataclass(frozen=True)
class ObjectInfo:
    size: int
    content_type: str | None


class ObjectStorage(Protocol):
    name: str

    async def put_stream(
        self, key: str, stream: AsyncIterator[bytes], content_type: str, max_bytes: int
    ) -> int:
        """Store the stream; return the byte count. Raise ``TooLarge`` past max_bytes."""

    async def put_file(self, key: str, fileobj: IO[bytes], content_type: str) -> None: ...

    async def head(self, key: str) -> ObjectInfo | None: ...

    def open_stream(
        self, key: str, chunk_size: int = 1024 * 1024, start: int = 0, end: int | None = None
    ) -> AsyncIterator[bytes]:
        """Yield bytes [start, end] (inclusive end, None = to the end of the object)."""

    async def read_prefix(self, key: str, length: int) -> bytes: ...

    async def download_to(self, key: str, path: str) -> None: ...

    async def delete(self, key: str) -> None: ...

    async def presigned_get(
        self, key: str, filename: str, content_type: str, ttl_seconds: int
    ) -> str | None:
        """A short-lived direct URL, or None when media must go through the API."""

    async def presigned_put(self, key: str, content_type: str, ttl_seconds: int) -> str | None: ...

    async def ping(self) -> None: ...


class TooLarge(Exception):
    pass
